css:
.tc-calc{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
.tc-calc__form{display:grid;gap:24px}
.tc-calc__pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.tc-calc__label{display:block;font:600 14px var(--font-heading,Oswald),sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--color-ink)}
.tc-calc__input{display:block;width:100%;box-sizing:border-box;margin-top:8px;padding:14px 16px;border:1px solid #b9b7ae;background:#fff;font:inherit;font-size:16px;color:var(--color-ink);border-radius:0}
.tc-calc__input:focus-visible{outline:2px solid var(--color-accent);outline-offset:2px}
.tc-calc__req{margin:0;font-size:14px;color:var(--color-muted)}
.tc-calc__out{background:var(--color-paper,#fafaf6);border:1px solid var(--color-line,#edebe3);padding:32px}
.tc-calc__dl{margin:0}
.tc-calc__row{padding:16px 0;border-bottom:1px solid var(--color-line,#edebe3)}
.tc-calc__row:first-child{padding-top:0}
.tc-calc__row--total{border-bottom:0;padding-bottom:0}
.tc-calc__dt{margin:0;font:600 13px var(--font-heading,Oswald),sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--color-muted)}
.tc-calc__dd{margin:4px 0 0;font:700 24px var(--font-heading,Oswald),sans-serif;color:var(--color-ink)}
.tc-calc__dd--big{font-size:36px;color:var(--color-accent)}
@media (max-width:900px){.tc-calc{grid-template-columns:1fr;gap:32px}}
@media (max-width:520px){.tc-calc__pair{grid-template-columns:1fr}}
